<script>
export default {
  props: {
    svgData: { type: Object, default: () => {} },
  },
  data() {
    return {};
  },
  created() {},
  beforeDestroy() {
    // 在组件生命周期结束的时候销毁。
    // window.removeEventListener("resize", this.resize, true);
  },
  mounted() {
    // window.addEventListener("resize", this.resize, true);
    let _this = this;
    var svgRootDom = this.$refs.overview;
    _this.adjustToFreezeWidth(svgRootDom);
    window.addEventListener("resize", () => {
      var svgRootDom = this.$refs.overview;
      _this.adjustToFreezeWidth(svgRootDom);
    });
  },
  methods: {
    // resize: _.debounce(function () {
    //   console.log("svg");
    //   var svgRootDom = this.$refs.overview;
    //   this.adjustToFreezeWidth(svgRootDom);
    // }, 200),

    adjustToFreezeWidth(rootSvg) {
      // var g = document.getElementById("g1").getBBox(); //元素g
      var g = this.$refs.overview_v.getBBox();
      var parentWidth = rootSvg.parentNode.offsetWidth; //svg父级的宽度
      var parentHeight = rootSvg.parentNode.offsetHeight; //svg父级的高度

      rootSvg.setAttribute("width", parentWidth);
      rootSvg.setAttribute("height", parentHeight);
      // viewBox="0 0 150 360
      // rootSvg.setAttribute("viewBox",`${g.x} ${g.y} ${g.width} ${g.height}`)
      rootSvg.setAttribute(
        "viewBox",
        "" + g.x + " " + (g.y - 30) + " " + g.width + " " + (g.height + 40) + ""
      );
    },
  },
};
</script>
